import{b as o,O as a,g as e,j as l}from"./chunks/framework.DcaUmd3X.js";const p=JSON.parse('{"title":"探索式测试（上）—— 思维框架","description":"","frontmatter":{},"headers":[],"relativePath":"testing/methodology/exploratory-testing-1/index.md","filePath":"测试理论与实践/3.测试方法体系/08.探索式测试（上）.md","lastUpdated":1781688244000}'),r={name:"testing/methodology/exploratory-testing-1/index.md"};function n(i,t,d,s,u,h){return a(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="探索式测试-上-——-思维框架" tabindex="-1">探索式测试（上）—— 思维框架 <a class="header-anchor" href="#探索式测试-上-——-思维框架" aria-label="Permalink to &quot;探索式测试（上）—— 思维框架&quot;">​</a></h1><blockquote><p>传统测试像&quot;按菜谱做菜&quot;——照着用例一步步来。探索式测试像&quot;逛菜市场&quot;——你知道要找什么，但路线和节奏是在逛的过程中决定的。</p></blockquote><h2 id="什么是探索式测试" tabindex="-1">什么是探索式测试 <a class="header-anchor" href="#什么是探索式测试" aria-label="Permalink to &quot;什么是探索式测试&quot;">​</a></h2><p>传统的脚本测试是这样工作的：先写好测试用例，然后照着用例一步步执行。用例是设计好的，执行是机械的。这套方法在需求稳定、流程清晰的场景下没问题——但软件总有出乎意料的行为。</p><p>探索式测试换了一个思路：<strong>测试设计、测试执行、学习是在同一时间发生的。</strong> 你一边测、一边观察结果、一边决定下一步往哪走。</p><p>打个比方：</p><ul><li>脚本测试 = 按导航开车。路线规划好了，你跟着走就行</li><li>探索式测试 = 在陌生城市闲逛。你知道大概想找什么（好吃的、好逛的），但具体往哪拐取决于你看到了什么</li></ul><p>探索式测试不是&quot;随便点点看看会不会崩&quot;。它有自己的方法论、工具和纪律。Elisabeth Hendrickson 在《探索式测试》里把它总结成了一套可教可学的体系——这也是这两章的核心。</p><h3 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>为什么探索式更适合</th></tr></thead><tbody><tr><td>需求不完整或模糊</td><td>没有清晰的用例可写，只能边测边理解</td></tr><tr><td>新接手一个系统</td><td>通过探索快速建立对系统的认知地图</td></tr><tr><td>自动化回归之后</td><td>脚本覆盖了&quot;你知道的&quot;，探索发现&quot;你不知道你不知道的&quot;</td></tr><tr><td>时间紧张</td><td>没法写完整用例时，一个限时会话就能产出有效信息</td></tr><tr><td>被测对象是 API 或后端服务</td><td>没有 UI 可以点，但同样可以探索输入空间和边界</td></tr></tbody></table><h2 id="探测章程-探索的指南针" tabindex="-1">探测章程：探索的指南针 <a class="header-anchor" href="#探测章程-探索的指南针" aria-label="Permalink to &quot;探测章程：探索的指南针&quot;">​</a></h2><p>传统测试用&quot;测试用例&quot;来指导执行，探索式测试用<strong>探测章程（Charter）</strong>。</p><h3 id="章程长什么样" tabindex="-1">章程长什么样 <a class="header-anchor" href="#章程长什么样" aria-label="Permalink to &quot;章程长什么样&quot;">​</a></h3><p>章程不定义具体步骤，而是定义<strong>探索的方向和边界</strong>。它的模板只有一句话：</p><blockquote><p><strong>用 [什么资源/方法]，探索 [什么目标]，以发现 [什么信息]。</strong></p></blockquote><p>几个真实示例：</p><table tabindex="0"><thead><tr><th>坏章程（太模糊）</th><th>好章程（有方向有边界）</th></tr></thead><tbody><tr><td>&quot;测一下登录功能&quot;</td><td>&quot;用 SQL 注入和 XSS 攻击载荷，探索登录表单的输入校验，以发现安全漏洞&quot;</td></tr><tr><td>&quot;看看支付有没有问题&quot;</td><td>&quot;用 3 种支付方式 + 5 种优惠券组合，探索结算流程，以发现金额计算错误&quot;</td></tr><tr><td>&quot;测试搜索&quot;</td><td>&quot;用特殊字符和超长字符串作为搜索词，探索搜索接口的异常处理，以发现崩溃和数据泄露风险&quot;</td></tr></tbody></table><p>好章程的特征：</p><ul><li><strong>有焦点</strong>：不说&quot;测什么功能&quot;，而是说&quot;从哪个角度挖&quot;</li><li><strong>有边界</strong>：不是说&quot;把所有情况都测一遍&quot;，而是限定了资源和方向</li><li><strong>有目标</strong>：不是说&quot;找 bug&quot;，而是具体到&quot;发现输入校验漏洞&quot;或&quot;发现金额计算错误&quot;</li></ul><h3 id="怎么生成好章程" tabindex="-1">怎么生成好章程 <a class="header-anchor" href="#怎么生成好章程" aria-label="Permalink to &quot;怎么生成好章程&quot;">​</a></h3><p>不是拍脑袋想。Hendrickson 提供了一个叫<strong>噩梦头条（Nightmare Headline）</strong> 的方法：</p><blockquote><p>假设明天产品上线，你希望<strong>不要</strong>看到什么新闻标题？</p></blockquote><p>比如：</p><ul><li>&quot;某支付 App 上线首日，用户重复扣款数千笔&quot;</li><li>&quot;某社交产品泄露百万用户手机号&quot;</li><li>&quot;某电商大促，购物车全部清零&quot;</li></ul><p>这些&quot;噩梦&quot;就是你该写章程的方向。把噩梦变成章程：</p><p>&quot;噩梦：重复扣款&quot; → 章程：&quot;用并发请求模拟同一订单多次支付，探索支付接口幂等性，以发现重复扣款风险&quot;</p><h3 id="章程-vs-测试用例" tabindex="-1">章程 vs 测试用例 <a class="header-anchor" href="#章程-vs-测试用例" aria-label="Permalink to &quot;章程 vs 测试用例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>测试用例</th><th>探测章程</th></tr></thead><tbody><tr><td>指导什么</td><td>怎么测（步骤）</td><td>往哪测（方向）</td></tr><tr><td>弹性</td><td>低，改了功能要改用例</td><td>高，方向不变细节可调</td></tr><tr><td>适合场景</td><td>回归验证</td><td>新功能探索、风险挖掘</td></tr><tr><td>输出</td><td>通过/失败的判定</td><td>发现的问题 + 对系统的理解</td></tr></tbody></table><h2 id="限时会话-让探索有节奏" tabindex="-1">限时会话：让探索有节奏 <a class="header-anchor" href="#限时会话-让探索有节奏" aria-label="Permalink to &quot;限时会话：让探索有节奏&quot;">​</a></h2><p>有了章程，下一步是<strong>设定时间盒（Time-box）</strong>，把探索装进一个有限的时间窗口。通常一个会话是 <strong>60 到 120 分钟</strong>。</p><h3 id="为什么需要时间盒" tabindex="-1">为什么需要时间盒 <a class="header-anchor" href="#为什么需要时间盒" aria-label="Permalink to &quot;为什么需要时间盒&quot;">​</a></h3><p>没有时间限制的探索 = 永远在探索。</p><p>时间盒倒逼你：</p><ul><li>在有限时间内聚焦章程，不被无关的发现带偏</li><li>到了时间停下来复盘——而不像无限制测试那样&quot;测到哪算哪&quot;</li><li>容易安排进日历——&quot;下午两点到四点，一次探索会话&quot;比&quot;有空就测&quot;靠谱一百倍</li></ul><h3 id="会话的节奏" tabindex="-1">会话的节奏 <a class="header-anchor" href="#会话的节奏" aria-label="Permalink to &quot;会话的节奏&quot;">​</a></h3><p>一次 90 分钟的会话可以这样分配：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前 5 分钟： 审阅章程，明确今天要挖什么</span></span>
<span class="line"><span>中间 70 分钟：执行探索，边测边记</span></span>
<span class="line"><span>最后 15 分钟：整理笔记，列出发现的问题</span></span></code></pre></div><h3 id="会话输出" tabindex="-1">会话输出 <a class="header-anchor" href="#会话输出" aria-label="Permalink to &quot;会话输出&quot;">​</a></h3><p>每个会话结束时，留下三样东西：</p><ol><li><strong>测试笔记</strong>：你试了什么、做了什么操作、看到了什么结果——不用写得漂亮，但要让另一个人能看懂</li><li><strong>问题清单</strong>：发现的所有问题，不管是不是 bug——包括&quot;这里的行为很奇怪但不确定算不算 bug&quot;</li><li><strong>章程状态</strong>：这个章程完成了吗？需要再来一个会话吗？</li></ol><blockquote><p>会话笔记不是负担，是你的记忆外挂。一个 90 分钟的会话，如果不记录，三天后你只能回忆起 20%。花 15 分钟记下来，三个月后还能复现。</p></blockquote><h2 id="测试启发法-经验的速查表" tabindex="-1">测试启发法：经验的速查表 <a class="header-anchor" href="#测试启发法-经验的速查表" aria-label="Permalink to &quot;测试启发法：经验的速查表&quot;">​</a></h2><p>经验丰富的测试人员不是记忆力好，而是<strong>脑子里有一份&quot;容易出错的地方&quot;的清单</strong>，每次测试时自动扫描。Hendrickson 把这套&quot;经验清单&quot;系统化为<strong>测试启发法速查表</strong>，这是她最著名的贡献之一。</p><h3 id="核心启发法" tabindex="-1">核心启发法 <a class="header-anchor" href="#核心启发法" aria-label="Permalink to &quot;核心启发法&quot;">​</a></h3><h4 id="零、一、多-zero-one-many" tabindex="-1">零、一、多（Zero, One, Many） <a class="header-anchor" href="#零、一、多-zero-one-many" aria-label="Permalink to &quot;零、一、多（Zero, One, Many）&quot;">​</a></h4><p>测试任何涉及&quot;数量&quot;的场景时，重点测这三个值：</p><ul><li><strong>0</strong>：空列表、无输入、没有任何依赖</li><li><strong>1</strong>：一条记录、一个元素、刚好一个</li><li><strong>多</strong>：两条记录、大量记录、超出屏幕的数据量</li></ul><p>比如测试一个待办列表：</p><ul><li>0 条待办 → 列表应该显示什么？空状态提示有没有？</li><li>1 条待办 → 删除按钮正常吗？删除后列表为空，状态对吗？</li><li>50 条待办 → 滚动正常吗？加载性能怎样？</li></ul><h4 id="一些、没有、全部-some-none-all" tabindex="-1">一些、没有、全部（Some, None, All） <a class="header-anchor" href="#一些、没有、全部-some-none-all" aria-label="Permalink to &quot;一些、没有、全部（Some, None, All）&quot;">​</a></h4><p>测试涉及&quot;选择/筛选/批量操作&quot;的场景：</p><ul><li><strong>全选 + 批量删除</strong> → 全部删完后页面状态正常吗？</li><li><strong>不选任何 + 点删除</strong> → 有没有给出&quot;请先选择&quot;的提示？</li><li><strong>选几条 + 操作</strong> → 只删了选中的还是全删了？</li></ul><h4 id="开头、中间、结尾-beginning-middle-end" tabindex="-1">开头、中间、结尾（Beginning, Middle, End） <a class="header-anchor" href="#开头、中间、结尾-beginning-middle-end" aria-label="Permalink to &quot;开头、中间、结尾（Beginning, Middle, End）&quot;">​</a></h4><p>测试涉及&quot;顺序/位置&quot;的场景：</p><ul><li>一个长列表，编辑<strong>第一个</strong>元素、<strong>最后一个</strong>元素、<strong>中间某个</strong>元素——每个位置的行为一致吗？</li><li>一个时间线，在<strong>最开始</strong>插入一条记录、在<strong>最末尾</strong>插入、在<strong>中间</strong>插入——排序都对吗？</li></ul><h4 id="违反数据格式规则" tabindex="-1">违反数据格式规则 <a class="header-anchor" href="#违反数据格式规则" aria-label="Permalink to &quot;违反数据格式规则&quot;">​</a></h4><p>输入框接受什么？偏不按格式来：</p><ul><li>手机号框 → 输入字母、输入超长数字、输入特殊符号</li><li>邮箱框 → 不输入 @、输入两个 @、输入中文</li><li>金额框 → 输入负数、输入 0、输入科学计数法 1e10</li></ul><h4 id="位置有关" tabindex="-1">位置有关 <a class="header-anchor" href="#位置有关" aria-label="Permalink to &quot;位置有关&quot;">​</a></h4><p>同一个元素出现在不同位置，行为应该一致但往往不一致：</p><ul><li>列表页的&quot;删除&quot;按钮 vs 详情页的&quot;删除&quot;按钮——走的是同一段代码吗？</li><li>首页的搜索框 vs 列表页的搜索框——搜出来的结果一样吗？</li></ul><h3 id="启发法不是检查表" tabindex="-1">启发法不是检查表 <a class="header-anchor" href="#启发法不是检查表" aria-label="Permalink to &quot;启发法不是检查表&quot;">​</a></h3><p>不要把启发法当成&quot;必须逐条执行的检查清单&quot;。它的正确用法是——每次开始测一个新功能时，扫一眼这份启发法列表，看哪些&quot;容易出错的角度&quot;适合当前场景。挑 3~5 个方向挖下去，比走马观花扫完全部更有用。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>探索式测试是<strong>边测、边学、边决定下一步</strong>的测试方式——不是&quot;随便点&quot;，而是有方法论支撑的思维框架</li><li>探测章程是探索的指南针：格式为&quot;用 [资源] 探索 [目标] 以发现 [信息]&quot;，用&quot;噩梦头条&quot;方法生成好章程</li><li>限时会话（60~120 分钟）给探索设定节奏——有开始有结束，有输出有复盘</li><li>测试启发法是经验速查表——零一多、一些没有全部、开头中间结尾、违反格式、位置有关——用来引导探索方向，不是逐条执行的清单</li></ol>`,65)])])}const g=o(r,[["render",n]]);export{p as __pageData,g as default};
